Lemma mb_land_neg8 : forall x, 0 <= x -> Z.land x (-8) = x - x mod 8.
Proof.
  intros x Hx. change (-8) with (Z.lnot (Z.ones 3)). rewrite <- Z.ldiff_land.
  rewrite Z.ldiff_ones_r by lia. rewrite Z.shiftr_div_pow2, Z.shiftl_mul_pow2 by lia.
  change (2^3) with 8. rewrite Zmod_eq by lia. lia.
Qed.
Lemma mb_land_M8 : forall x, 0 <= x < 2^64 -> Z.land x 18446744073709551608 = x - x mod 8.
Proof.
  intros x Hx. change 18446744073709551608 with (Z.land (Z.ones 64) (-8)).
  rewrite Z.land_assoc, Z.land_ones, Z.mod_small by lia. apply mb_land_neg8. lia.
Qed.
(* [comment removed for export] *)
Lemma mb_land_M8' : forall x, 0 <= x < 2^61 -> Z.land x 4611686018427387896 = x - x mod 8.
Proof.
  intros x Hx. change 4611686018427387896 with (Z.land (Z.ones 62) (-8)).
  rewrite Z.land_assoc, Z.land_ones, Z.mod_small by lia. apply mb_land_neg8. lia.
Qed.

Lemma mb_block_size_eq : forall s, 0 <= s -> mb_block_size s = s + 31 - (s + 31) mod 8.
Proof. intros s Hs. unfold mb_block_size. apply mb_land_neg8. lia. Qed.

