Definition AMBmid (m : mem) (b : Z) (es : list mbe) (insz n x : Z) : Prop :=
  AMBraw m b (mb_put_es es insz n x) (mb_mid_out b es insz x) insz (mb_outpos es insz) (mb_mid_outend es insz n).

(* [comment removed for export] *)
Lemma mb_shape_noneed : forall b es insz n, mb_ok es insz -> 1 <= n -> mb_need es insz n = false ->
  exists P xl sl, es = P ++ [(xl, sl)] /\ mb_full es insz = false /\ mb_put_es es insz n xl = es
    /\ mb_out b es insz = xl /\ mb_lasta b es = xl /\ mb_lasts es = sl /\ mb_capi es = mb_cap P
    /\ mb_outpos es insz = insz - mb_cap P /\ 1 <= insz - mb_cap P /\ insz - mb_cap P + n <= sl
    /\ mb_mid_outend es insz n = insz - mb_cap P + n /\ 0 <= mb_cap P.
Proof.
  intros b es insz n OK N1 ND. pose proof (mb_ok_bounds _ _ OK) as [B1 B2]. destruct OK as (E0 & E1 & F & G).
  unfold mb_need in ND. apply Z.ltb_ge in ND.
  assert (NE : es <> []). { intros ->. rewrite (E0 eq_refl) in ND. cbn in ND. lia. }
  specialize (E1 NE). destruct (mb_es_snoc_inv es NE) as (P & xl & sl & EP). subst es.
  exists P, xl, sl. rewrite mb_capi_snoc, mb_cap_snoc in *.
  assert (FU : mb_full (P ++ [(xl, sl)]) insz = false). { unfold mb_full. apply Z.eqb_neq. rewrite mb_cap_snoc. lia. }
  unfold mb_put_es, mb_out, mb_outpos, mb_mid_outend, mb_need. unfold mb_outpos.
  rewrite FU, mb_capi_snoc, mb_cap_snoc, mb_lasta_snoc, mb_lasts_snoc.
  replace (mb_cap P + sl <? insz + n) with false by (symmetry; apply Z.ltb_ge; lia).
  repeat split; try reflexivity; lia.
Qed.

Lemma mb_shape_full : forall b es insz n x, mb_ok es insz -> 1 <= n -> mb_full es insz = true ->
  mb_need es insz n = true /\ mb_put_es es insz n x = es ++ [(x, mb_grow es insz n)] /\ insz = mb_cap es
  /\ mb_out b es insz = b + 8 /\ mb_mid_out b es insz x = x /\ mb_outpos es insz = 0 /\ mb_mid_outend es insz n = n
  /\ n <= mb_grow es insz n /\ 0 <= insz.
Proof.
  intros b es insz n x OK N1 FU. pose proof (mb_ok_bounds _ _ OK) as [B1 B2].
  pose proof (mb_need_of_full es insz n FU N1) as ND.
  unfold mb_put_es, mb_out, mb_mid_out, mb_outpos, mb_mid_outend. rewrite ND, FU.
  unfold mb_full in FU. apply Z.eqb_eq in FU. unfold mb_grow. repeat split; try reflexivity; lia.
Qed.

Lemma mb_shape_part : forall b es insz n x, mb_ok es insz -> 1 <= n -> mb_full es insz = false -> mb_need es insz n = true ->
  exists P xl sl, es = P ++ [(xl, sl)] /\ mb_put_es es insz n x = es ++ [(x, mb_grow es insz n)]
    /\ mb_out b es insz = xl /\ mb_mid_out b es insz x = xl /\ mb_lasta b es = xl /\ mb_lasts es = sl /\ mb_capi es = mb_cap P
    /\ mb_outpos es insz = insz - mb_cap P /\ 1 <= insz - mb_cap P /\ insz - mb_cap P < sl /\ sl < insz - mb_cap P + n
    /\ mb_mid_outend es insz n = insz + n - (mb_cap P + sl) /\ insz + n - (mb_cap P + sl) <= mb_grow es insz n /\ 0 <= mb_cap P.
Proof.
  intros b es insz n x OK N1 FU ND. pose proof (mb_ok_bounds _ _ OK) as [B1 B2]. destruct OK as (E0 & E1 & F & G).
  assert (NE : es <> []). { intros ->. unfold mb_full in FU. rewrite (E0 eq_refl) in FU. cbn in FU. discriminate. }
  specialize (E1 NE). destruct (mb_es_snoc_inv es NE) as (P & xl & sl & EP). subst es.
  exists P, xl, sl. rewrite mb_capi_snoc, mb_cap_snoc in *.
  unfold mb_put_es, mb_out, mb_mid_out, mb_outpos, mb_mid_outend. unfold mb_outpos.
  rewrite ND, FU, mb_lasta_snoc, mb_lasts_snoc, mb_capi_snoc, mb_cap_snoc.
  unfold mb_full, mb_need in FU, ND. apply Z.eqb_neq in FU. apply Z.ltb_lt in ND. rewrite mb_cap_snoc in FU, ND.
  unfold mb_grow. rewrite mb_cap_snoc. repeat split; try reflexivity; lia.
Qed.

(* [comment removed for export] *)
Lemma mb_put_words : forall b es insz n x q (es' := mb_put_es es insz n x),
  mb_ok es insz -> 1 <= n ->
  q = insz + n - mb_capi es' ->
  mb_out b es' (insz + n) = (if q =? mb_lasts es' then b + 8 else mb_lasta b es')
  /\ mb_outpos es' (insz + n) = (if q =? mb_lasts es' then 0 else q).
Proof.
  intros b es insz n x q es' OK N1 Eq. subst es'.
  assert (NE : mb_put_es es insz n x <> []).
  { unfold mb_put_es. destruct (mb_need es insz n) eqn:ND; [destruct es; discriminate|].
    intros E. rewrite E in ND. unfold mb_need in ND. cbn in ND. destruct OK as (E0 & _). rewrite (E0 E) in ND. apply Z.ltb_ge in ND. lia. }
  unfold mb_out, mb_outpos, mb_full. rewrite (mb_cap_lasts _ NE).
  replace (insz + n =? mb_capi (mb_put_es es insz n x) + mb_lasts (mb_put_es es insz n x)) with (q =? mb_lasts (mb_put_es es insz n x)).
  2:{ destruct (Z.eqb_spec q (mb_lasts (mb_put_es es insz n x))); [symmetry; apply Z.eqb_eq; lia| symmetry; apply Z.eqb_neq; lia]. }
  destruct (q =? mb_lasts (mb_put_es es insz n x)); split; try reflexivity. lia.
Qed.

