Lemma mb_addr_ok_nil : forall b, aapp b 64 -> b mod 8 = 0 -> mb_addr_ok b [].
Proof.
  intros b H1 H3. split; [intros x s []|]. split; [intros x1 s1 x2 s2 []|]. split; [exact H1|]. split; [exact H3|]. intros x s [].
Qed.

Lemma mb_addr_ok_snoc : forall b es x s,
  mb_addr_ok b es -> 0 < x -> x mod 16 = 0 -> 0 <= s -> aapp x (mb_block_size s) ->
  (forall x2 s2, In (x2, s2) es -> x + mb_block_size s <= x2 \/ x2 + mb_block_size s2 <= x) ->
  (x + mb_block_size s <= b \/ b + 64 <= x) ->
  mb_addr_ok b (es ++ [(x, s)]).
Proof.
  intros b es x s (AD & DJ & HB & AL & SP) P XA S0 AP D DB. split; [| split; [| split; [exact HB| split; [exact AL|]]]].
  - intros x1 s1 IN. apply in_app_iff in IN. destruct IN as [IN|[E|[]]]; [exact (AD x1 s1 IN)|]. injection E as <- <-. auto.
  - intros x1 s1 x2 s2 I1 I2 NE. apply in_app_iff in I1. apply in_app_iff in I2.
    destruct I1 as [I1|[E1|[]]]; destruct I2 as [I2|[E2|[]]].
    + exact (DJ x1 s1 x2 s2 I1 I2 NE).
    + injection E2 as <- <-. destruct (D x1 s1 I1); [right| left]; assumption.
    + injection E1 as <- <-. exact (D x2 s2 I2).
    + injection E1 as <- <-. injection E2 as <- <-. exfalso. exact (NE eq_refl).
  - intros x1 s1 IN. apply in_app_iff in IN. destruct IN as [IN|[E|[]]]; [exact (SP x1 s1 IN)|]. injection E as <- <-. exact DB.
Qed.

(* [comment removed for export] *)
Lemma mb_addr_ok_elem : forall b es x s, mb_addr_ok b es -> In (x, s) es ->
  0 < x /\ x mod 16 = 0 /\ 0 <= s /\ s + 24 <= mb_block_size s /\ mb_block_size s mod 8 = 0
  /\ AIMG_TOP <= x /\ x + mb_block_size s <= aceil /\ x + mb_block_size s < AAPP_HI
  /\ aapp x (mb_block_size s) /\ (x + mb_block_size s <= b \/ b + 64 <= x).
Proof.
  intros b es x s (AD & _ & _ & _ & SP) IN. destruct (AD x s IN) as (P & Q & R & T).
  pose proof (mb_block_size_range s R) as [[R1 R2] R3].
  pose proof (aapp_bounds _ _ T ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  repeat (split; [first [assumption| lia]|]). exact (SP x s IN).
Qed.

Lemma mb_addr_ok_obj : forall b es, mb_addr_ok b es ->
  AIMG_TOP <= b /\ b + 64 <= aceil /\ b + 64 < AAPP_HI /\ 0 < b /\ b mod 8 = 0 /\ aapp b 64.
Proof.
  intros b es (_ & _ & HB & AL & _). pose proof (aapp_bounds _ _ HB ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  repeat (split; [first [assumption| lia]|]). exact HB.
Qed.

