Lemma AMBElems_lookup : forall m es x s, AMBElems m es -> In (x, s) es ->
  exists junk, rw_cells asegs m (x + 16) [C8 (wz s); CB (Z.to_nat (mb_block_size s - 24)) junk].
Proof. intros m es x s H IN. exact (H x s IN). Qed.

Lemma AMBElems_nil : forall m, AMBElems m [].
Proof. intros m x s []. Qed.

Lemma AMBShad_nil : forall m, AMBShad m [].
Proof. intros m x s []. Qed.
