Lemma awin_win_fr : forall ff k iv, awin iv -> win_fr ff k iv.
Proof. intros ff k [l h] (_ & _ & K). unfold win_fr. cbn [fst snd] in *. destruct K; [left| right; left]; assumption. Qed.

Lemma awin_fr_win_fr : forall ff k iv, 0 <= ff -> awin_fr ff k iv -> win_fr ff (fshn k) iv.
Proof.
  intros ff k [l h] F0 [K|[K1 K2]]; [apply awin_win_fr; exact K|].
  unfold win_fr. right; right. cbn [fst snd] in *. pose proof (sh_shiftr ff F0) as SS. rewrite ASHADOW_BASE_val in SS. lia.
Qed.

(* [comment removed for export] *)
Lemma AMBElems_transport_stack : forall SP W m m' b es,
  AMBElems m es -> mb_addr_ok b es -> munch W m m' -> wmono asegs m m' -> stackW SP W -> AMBElems m' es.
Proof.
  intros SP W m m' b es H AOK MU WM SW. eapply AMBElems_transport; [exact H| exact MU| exact WM|].
  intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (P & _ & S0 & R1 & _ & _ & R2 & _). split; [lia|].
  eapply stackW_disjoint_low; [exact SW| lia].
Qed.

(* [comment removed for export] *)
Lemma mb_In_unique : forall (es : list mbe) x s1 s2, NoDup (map fst es) -> In (x, s1) es -> In (x, s2) es -> s1 = s2.
Proof.
  induction es as [|[y t] es IH]; intros x s1 s2 ND I1 I2; [destruct I1|].
  cbn in ND. apply list.NoDup_cons in ND. destruct ND as [NI ND].
  destruct I1 as [E1|I1]; destruct I2 as [E2|I2].
  - congruence.
  - injection E1 as -> ->. exfalso. apply NI. apply list_elem_of_In. apply in_map_iff. exists (x, s2). split; [reflexivity| exact I2].
  - injection E2 as -> ->. exfalso. apply NI. apply list_elem_of_In. apply in_map_iff. exists (x, s1). split; [reflexivity| exact I1].
  - exact (IH x s1 s2 ND I1 I2).
Qed.

Lemma mb_L_nodup : forall hL (es : list mbe) ls, dl_ok hL (map fst es) ls -> NoDup (map fst es).
Proof. intros hL es ls (N & _ & _). exact (nd_cons_tl _ _ (nd_cons_tl _ _ N)). Qed.

(* [comment removed for export] *)
Lemma AMBElems_update : forall W m m' b es x s junk',
  AMBElems m es -> mb_addr_ok b es -> NoDup (map fst es) -> In (x, s) es ->
  munch W m m' -> wmono asegs m m' ->
  (forall x2 s2, In (x2, s2) es -> x2 <> x -> disjoint_from W (x2 + 16) (mb_block_size s2 - 16)) ->
  rw_cells asegs m' (x + 16) [C8 (wz s); CB (Z.to_nat (mb_block_size s - 24)) junk'] ->
  AMBElems m' es.
Proof.
  intros W m m' b es x s junk' H AOK ND IN MU WM D C x2 s2 IN2.
  destruct (Z.eq_dec x2 x) as [->|NE].
  - rewrite (mb_In_unique es x s2 s ND IN2 IN). exists junk'. exact C.
  - destruct (H x2 s2 IN2) as [j2 C2]. exists j2. destruct (mb_addr_ok_elem _ _ _ _ AOK IN2) as (_ & _ & S2 & R1 & _).
    eapply rw_cells_transport; [exact C2| exact MU| exact WM|]. cbn [cells_size csize]. rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia.
    replace (x2 + 16) with (x2 + 16 + 0) by lia. eapply disjoint_from_sub; [exact (D x2 s2 IN2 NE)| lia| lia].
Qed.

(* [comment removed for export] *)
Lemma AMBElems_snoc : forall m es x s junk,
  AMBElems m es -> rw_cells asegs m (x + 16) [C8 (wz s); CB (Z.to_nat (mb_block_size s - 24)) junk] -> AMBElems m (es ++ [(x, s)]).
Proof.
  intros m es x s junk H C x2 s2 IN2. apply in_app_iff in IN2. destruct IN2 as [IN2|[E|[]]].
  - exact (H x2 s2 IN2).
  - injection E as <- <-. exists junk. exact C.
Qed.

