(* [comment removed for export] *)
Lemma AMBraw_transport_gen : forall W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W b 64 -> (forall x, b <= x < b + 64 -> outside W (sh x)) ->
  (forall x s, In (x, s) es -> disjoint_from W x (mb_block_size s) /\ disjoint_from W (sh x) (nsh (mb_block_size s))) ->
  AMBraw m' b es out insz outpos outend.
Proof.
  intros W m m' b es out insz outpos outend (ls & H0 & H1 & DL & LC & EL & AOK & SH & AB) MU WM DB OB DE.
  exists ls. split. { eapply rw_cells_transport; [exact H0| exact MU| exact WM|]. eapply disjoint_from_sub; [exact DB| lia| cbn; lia]. }
  split. { eapply rw_cells_transport; [exact H1| exact MU| exact WM|]. eapply disjoint_from_sub; [exact DB| lia| cbn; lia]. }
  split; [exact DL|]. split.
  { eapply ALSCells_transport; [exact LC| exact MU| exact WM|]. intros a n La.
    destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(s & IN)].
    - eapply disjoint_from_sub; [exact DB| lia| lia].
    - destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). eapply disjoint_from_sub; [exact (proj1 (DE a s IN))| lia| lia]. }
  split.
  { eapply AMBElems_transport; [exact EL| exact MU| exact WM|].
    intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). split; [lia|].
    eapply disjoint_from_sub; [exact (proj1 (DE x s IN))| lia| lia]. }
  split; [exact AOK|]. split.
  { eapply AMBShad_transport; [exact SH| exact MU| exact WM|]. intros x s IN. exact (proj2 (DE x s IN)). }
  eapply accessible_transport; [exact AB| exact MU| exact OB].
Qed.

(* [comment removed for export] *)
Definition mwin (b : Z) (es : list mbe) (iv : Z * Z) : Prop :=
  awin iv /\ (b + 64 <= fst iv \/ snd iv <= b)
  /\ forall x s, In (x, s) es -> x + mb_block_size s <= fst iv \/ snd iv <= x.

Lemma mwin_stack : forall b es lo hi, mb_addr_ok b es -> aceil <= lo -> mwin b es (lo, hi).
Proof.
  intros b es lo hi AOK CE. pose proof (mb_addr_ok_obj _ _ AOK) as (_ & B2 & _).
  split; [apply awin_stack; exact CE|]. split; [left; cbn [fst snd]; lia|].
  intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & _ & _ & _ & _ & R & _). left. cbn [fst snd]. lia.
Qed.

Lemma mwin_disjoint : forall b es W a n, Forall (mwin b es) W ->
  (b <= a /\ a + n <= b + 64) \/ (exists x s, In (x, s) es /\ x <= a /\ a + n <= x + mb_block_size s) ->
  disjoint_from W a n.
Proof.
  induction W as [|[l h] W IH]; intros a n FW HIN; cbn; [exact I|].
  pose proof (Forall_inv FW) as (_ & K1 & K2). cbn [fst snd] in K1, K2. split; [| apply IH; [exact (Forall_inv_tail FW)| exact HIN]].
  destruct HIN as [[H1 H2]|(x & s & IN & H1 & H2)]; [lia| destruct (K2 x s IN); lia].
Qed.

Lemma mwin_awin : forall b es W, Forall (mwin b es) W -> Forall awin W.
Proof. intros b es W F. eapply Forall_impl; [| exact F]. intros iv (K & _). exact K. Qed.

Lemma AMBraw_transport_win : forall W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono asegs m m' -> Forall (mwin b es) W ->
  AMBraw m' b es out insz outpos outend.
Proof.
  intros W m m' b es out insz outpos outend R MU WM FW.
  pose proof R as (ls & _ & _ & _ & _ & _ & AOK & _ & _).
  pose proof (mb_addr_ok_obj _ _ AOK) as (B1 & B2 & B3 & B4 & B5 & _). pose proof (mwin_awin _ _ _ FW) as FA.
  eapply AMBraw_transport_gen; [exact R| exact MU| exact WM| | |].
  - eapply mwin_disjoint; [exact FW| left; lia].
  - intros x Hx. apply awin_outside_sh; [exact FA| lia].
  - intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (P & _ & S0 & R1 & _ & R2 & R3 & R4 & _). split.
    + eapply mwin_disjoint; [exact FW| right; exists x, s; split; [exact IN| lia]].
    + apply awin_disjoint_shland; [exact FA| apply sh_ge_lowsh; lia| apply sh_nsh_high; lia].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_transport : forall SP W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono asegs m m' -> stackW SP W ->
  AMBraw m' b es out insz outpos outend.
Proof.
  intros SP W m m' b es out insz outpos outend R MU WM SW.
  pose proof R as (ls & _ & _ & _ & _ & _ & AOK & _ & _).
  eapply AMBraw_transport_win; [exact R| exact MU| exact WM|].
  eapply Forall_impl; [| exact SW]. intros [l h] [K _]. cbn [fst snd] in K. apply mwin_stack; [exact AOK| exact K].
Qed.

(* [comment removed for export] *)
Definition mwin_fr (b : Z) (es : list mbe) (ff k : Z) (iv : Z * Z) : Prop :=
  mwin b es iv \/ (sh ff <= fst iv /\ snd iv <= sh ff + k).

