(* [comment removed for export] *)
Lemma AMBraw_update : forall W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono asegs m m' -> Forall awin W ->
  disjoint_from W b 64 ->
  (forall x s, In (x, s) es -> disjoint_from W x 24) ->
  (forall x s, In (x, s) es -> disjoint_from W (x + 16) (mb_block_size s - 16)
                              \/ exists junk', rw_cells asegs m' (x + 16) [C8 (wz s); CB (Z.to_nat (mb_block_size s - 24)) junk']) ->
