Lemma AMBuf_transport : forall SP W m m' b es insz,
  AMBuf m b es insz -> munch W m m' -> wmono asegs m m' -> stackW SP W -> AMBuf m' b es insz.
Proof. intros SP W m m' b es insz [R OK] MU WM SW. split; [| exact OK]. eapply AMBraw_transport; eauto. Qed.

Lemma AMBuf_transport_win : forall W m m' b es insz,
  AMBuf m b es insz -> munch W m m' -> wmono asegs m m' -> Forall (mwin b es) W -> AMBuf m' b es insz.
Proof. intros W m m' b es insz [R OK] MU WM FW. split; [| exact OK]. eapply AMBraw_transport_win; eauto. Qed.

Lemma AMBuf_transport_gen : forall W m m' b es insz,
  AMBuf m b es insz -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W b 64 -> (forall x, b <= x < b + 64 -> outside W (sh x)) ->
  (forall x s, In (x, s) es -> disjoint_from W x (mb_block_size s) /\ disjoint_from W (sh x) (nsh (mb_block_size s))) ->
  AMBuf m' b es insz.
Proof. intros W m m' b es insz [R OK] MU WM DB OB DE. split; [| exact OK]. eapply AMBraw_transport_gen; eauto. Qed.

