Proof. intros m b es out insz outpos outend (ls & _ & _ & _ & _ & _ & AOK & _). exact AOK. Qed.
Lemma AMBraw_acc : forall m b es out insz outpos outend, AMBraw m b es out insz outpos outend -> accessible m b 64.
Proof. intros m b es out insz outpos outend (ls & _ & _ & _ & _ & _ & _ & _ & AB). exact AB. Qed.
Lemma AMBraw_shad : forall m b es out insz outpos outend, AMBraw m b es out insz outpos outend -> AMBShad m es.
Proof. intros m b es out insz outpos outend (ls & _ & _ & _ & _ & _ & _ & SH & _). exact SH. Qed.
Lemma AMBraw_elems : forall m b es out insz outpos outend, AMBraw m b es out insz outpos outend -> AMBElems m es.
Proof. intros m b es out insz outpos outend (ls & _ & _ & _ & _ & EL & _). exact EL. Qed.
Lemma AMBraw_nodup : forall m b es out insz outpos outend, AMBraw m b es out insz outpos outend -> NoDup (map fst es).
Proof. intros m b es out insz outpos outend (ls & _ & _ & DL & _). exact (mb_L_nodup _ _ _ DL). Qed.

