Lemma AMBraw_elem_acc : forall m b es out insz outpos outend x s a k,
  AMBraw m b es out insz outpos outend -> In (x, s) es -> x <= a -> a + k <= x + mb_block_size s -> accessible m a k.
Proof.
  intros m b es out insz outpos outend x s a k R IN H1 H2.
  pose proof (AMBraw_addr_ok _ _ _ _ _ _ _ R) as AOK. pose proof (AMBraw_shad _ _ _ _ _ _ _ R) as SH.
  destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (P & _ & S0 & R1 & _ & R2 & R3 & R4 & _).
  eapply addressable_accessible; [exact (SH x s IN)| exact H1| exact H2| lia].
Qed.

